import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, time, uniform } from 'three/tsl';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Object3D, Mesh, Color } = ctx.THREE;
  const root = new Group();

  // Store cleanup actions
  const disposables = [];

  // Load GLB mesh
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const mesh = gltf.scene;
      root.add(mesh);
      // Dispose mesh resources on cleanup
      disposables.push({
        cleanup: () => {
          mesh.traverse((child) => {
            if (child.isMesh) {
              if (child.geometry) child.geometry.dispose();
              if (child.material) {
                if (Array.isArray(child.material)) {
                  child.material.forEach((m) => m.dispose());
                } else {
                  child.material.dispose();
                }
              }
            }
          });
        },
      });
    });
  }

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const instance = ctx.primitives[prim.name](root, prim.params);
      if (instance) disposables.push(instance);
    });
  }

  // Hover effect (rise-in subtle)
  const originalY = root.position.y;
  let hoverTimeline = null;
  const onHoverEnter = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: originalY + 0.15,
      duration: 0.2,
      ease: 'power2.out',
    });
  };
  const onHoverLeave = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: originalY,
      duration: 0.2,
      ease: 'power2.out',
    });
  };

  // Click handler emit event
  const onClick = () => {
    ctx.emit('hub-journal.select', {});
  };

  // Attach handlers
  root.userData.handlers = {
    hoverEnter: onHoverEnter,
    hoverLeave: onHoverLeave,
    click: onClick,
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    disposables.forEach((d) => {
      if (typeof d.cleanup === 'function') d.cleanup();
    });
    if (hoverTimeline) hoverTimeline.kill();
  };

  return root;
}
